from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

app = FastAPI()

@app.get("/query")
async def read_query(q: str = Query(None, validation_alias="query_alias")):
    return {"q": q}

class Item(BaseModel):
    name: str = Field(validation_alias="name_alias")

@app.post("/body")
async def read_body(item: Item):
    return {"name": item.name}

client = TestClient(app)

