    try:
        test_query_alias()
        print("test_query_alias passed")
        test_body_alias()
        print("test_body_alias passed")
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
    except Exception as e:
        print(f"An error occurred: {e}")
